//! Where a team came from (e.g. generated by AI), kept for its provenance label.
use super::Store;
use crate::views::TeamOrigin;
use rusqlite::{OptionalExtension, params};

impl Store {
    pub fn team_origin(&self, team: &str) -> rusqlite::Result<Option<TeamOrigin>> {
        let json: Option<String> = self
            .conn
            .query_row(
                "SELECT json FROM team_origins WHERE team = ?1",
                [team],
                |r| r.get(0),
            )
            .optional()?;
        Ok(json.and_then(|j| serde_json::from_str(&j).ok()))
    }

    pub fn set_team_origin(&mut self, team: &str, origin: &TeamOrigin) -> rusqlite::Result<()> {
        self.conn.execute(
            "INSERT OR REPLACE INTO team_origins (team, json) VALUES (?1, ?2)",
            params![
                team,
                serde_json::to_string(origin).expect("origin serializes")
            ],
        )?;
        Ok(())
    }
}
